UPDATE articulos a SET contenido=(SELECT string_agg(coalesce(v.texto,substring(a.contenido from v.inicio for v.largo)),'' ORDER BY v.orden) FROM (VALUES (0, 1, 55, NULL::text),(1,0,0,E'<td colspan="2">'),(2, 60, 370, NULL::text)) v(orden,inicio,largo,texto)) WHERE a.id='9f61e592-29d4-5911-962d-8876e2f32b05' AND md5(a.contenido)='07ead9f69526c125cbee04b1cf6e86d0' RETURNING a.id,md5(a.contenido) hash;